const item = $input.first();
const body = item.json.body || item.json;

const patientId = body.patient_id || 'PAT-UNKNOWN';
const patientName = body.patient_name || 'Patient';
const diagnosisNarrative = body.diagnosis_narrative || 'N/A';
const icd10Code = body.icd10_code || '';
const cptCode = body.cpt_code || '';
const roomRentBilled = Number(body.room_rent_billed || 0);
const surgeryFeeBilled = Number(body.surgery_fee_billed || 0);
const medicineFeeBilled = Number(body.medicine_fee_billed || 0);
const sumInsured = Number(body.sum_insured || 0);

let confidenceScore = 1.0;
const discrepancyFlags = [];
const itemizedDeductions = [];

// 1. Code Consistency Check: K35.80 (Appendicitis) vs 44970 (Laparoscopic Appendectomy)
if (icd10Code === 'K35.80' && cptCode !== '44970') {
  confidenceScore -= 0.30;
  discrepancyFlags.push('CODING_MISMATCH: ICD-10 K35.80 (Appendicitis) requires CPT 44970 (Laparoscopic Appendectomy). Received CPT: ' + cptCode);
}

// 2. Room Rent Sub-Limit Check: Room rent billed exceeds 1% of sum_insured
const maxAllowedRoomRent = sumInsured * 0.01;
let roomRentDeduction = 0;
if (roomRentBilled > maxAllowedRoomRent) {
  roomRentDeduction = roomRentBilled - maxAllowedRoomRent;
  confidenceScore -= 0.15;
  discrepancyFlags.push('SUB_LIMIT_EXCEEDED: Room rent billed (₹' + roomRentBilled.toLocaleString() + ') exceeds 1% sum insured cap (₹' + maxAllowedRoomRent.toLocaleString() + ')');
  itemizedDeductions.push({
    category: 'Room Rent Sub-limit',
    claimed: roomRentBilled,
    allowed: maxAllowedRoomRent,
    deducted: roomRentDeduction,
    reason: 'Breaches 1% sum insured sub-limit'
  });
}

// Financial Totals Calculation
const totalBilled = roomRentBilled + surgeryFeeBilled + medicineFeeBilled;
const totalDeducted = roomRentDeduction;
const totalApproved = Math.max(0, totalBilled - totalDeducted);
const finalConfidence = Math.max(0, Number(confidenceScore.toFixed(2)));

// Status Determination
const status = (finalConfidence >= 0.85 && discrepancyFlags.length === 0) ? 'APPROVED' : 'PENDING_REVIEW';

return [{
  json: {
    status,
    patient_id: patientId,
    patient_name: patientName,
    diagnosis_narrative: diagnosisNarrative,
    icd10_code: icd10Code,
    cpt_code: cptCode,
    confidence_score: finalConfidence,
    discrepancy_flags: discrepancyFlags,
    financial_breakdown: {
      room_rent_billed: roomRentBilled,
      surgery_fee_billed: surgeryFeeBilled,
      medicine_fee_billed: medicineFeeBilled,
      sum_insured: sumInsured,
      max_allowed_room_rent: maxAllowedRoomRent,
      total_billed: totalBilled,
      total_deducted: totalDeducted,
      total_approved: totalApproved,
      deductions: itemizedDeductions
    },
    adjudication_timestamp: new Date().toISOString()
  }
}];
